(function(){var d=document;var l=d.createElement('link');l.rel='stylesheet';l.href='/assets/css/style.min.css?v=1';d.head.appendChild(l);var mb=d.querySelector('.menu-btn'),nav=d.getElementById('site-nav');if(mb&&nav){mb.addEventListener('click',function(){var o=nav.classList.toggle('open');mb.setAttribute('aria-expanded',o?'true':'false');});}var dds=d.querySelectorAll('.dd-btn');for(var i=0;i<dds.length;i++){dds[i].addEventListener('click',function(e){var li=this.parentNode,o=li.classList.toggle('open');this.setAttribute('aria-expanded',o?'true':'false');});}d.addEventListener('keydown',function(e){if(e.key==='Escape'){var op=d.querySelectorAll('.has-dd.open');for(var j=0;j<op.length;j++){op[j].classList.remove('open');op[j].querySelector('.dd-btn').setAttribute('aria-expanded','false');}}});d.addEventListener('click',function(e){var a=e.target.closest&&e.target.closest('a[href^="tel:"]');if(a){window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:'call_click',call_location:a.getAttribute('data-loc')||'inline',page_path:location.pathname});}});})();